const alert = $json;
const text = `${alert.rule_description ?? ''}\n${alert.full_log ?? ''}`.toLowerCase();

// Conservative MVP keyword mapping. These are candidate mappings, not proof
// that a technique occurred. Each result includes the matched evidence.
const rules = [
  { pattern: /\b(brute.?force|multiple failed logins|repeated failed password|password guessing)\b/i,
    id: 'T1110', name: 'Brute Force' },
  { pattern: /\bpowershell\b/i,
    id: 'T1059.001', name: 'PowerShell' },
  { pattern: /\b(command prompt|cmd\.exe|windows command shell)\b/i,
    id: 'T1059.003', name: 'Windows Command Shell' },
  { pattern: /\b(credential dump|lsass|mimikatz)\b/i,
    id: 'T1003', name: 'OS Credential Dumping' },
  { pattern: /\b(scheduled task|schtasks)\b/i,
    id: 'T1053.005', name: 'Scheduled Task' },
  { pattern: /\b(phishing email|spearphishing attachment)\b/i,
    id: 'T1566.001', name: 'Spearphishing Attachment' },
  { pattern: /\b(ssh remote login|remote ssh)\b/i,
    id: 'T1021.004', name: 'SSH' }
];

const mitre_mapping = rules
  .filter(rule => rule.pattern.test(text))
  .map(rule => ({
    technique_id: rule.id,
    technique_name: rule.name,
    framework: 'MITRE ATT&CK',
    mapping_status: 'candidate',
    evidence: text.match(rule.pattern)?.[0] ?? ''
  }));

return [{ json: { ...alert, mitre_mapping } }];

