={{ {
  statement: "MATCH (current:Alert {id: $alert_id}) OPTIONAL MATCH (current)-[:SOURCE_IP]->(ip:IP)<-[:SOURCE_IP]-(ipAlert:Alert) WHERE ipAlert.id <> current.id WITH current, collect(DISTINCT CASE WHEN ipAlert IS NOT NULL THEN {alert_id: ipAlert.id, timestamp: toString(ipAlert.timestamp), rule_id: ipAlert.rule_id, description: ipAlert.description, rule_level: ipAlert.rule_level, correlation_type: 'shared_ip', matched_value: ip.value} END) AS ip_matches OPTIONAL MATCH (current)-[:OBSERVED_ON]->(host:Host)<-[:OBSERVED_ON]-(hostAlert:Alert) WHERE hostAlert.id <> current.id WITH ip_matches, collect(DISTINCT CASE WHEN hostAlert IS NOT NULL THEN {alert_id: hostAlert.id, timestamp: toString(hostAlert.timestamp), rule_id: hostAlert.rule_id, description: hostAlert.description, rule_level: hostAlert.rule_level, correlation_type: 'shared_host', matched_value: host.id} END) AS host_matches RETURN [x IN ip_matches WHERE x IS NOT NULL] + [x IN host_matches WHERE x IS NOT NULL] AS related_alerts",
  parameters: { alert_id: $json.alert_id }
} }}

