const alert = $('MITRE ATT&CK - Rule-Based Mapping').first().json;
const response = $json;

// Neo4j Query API v2 returns rows under data[0]. The query returns one
// column (related_alerts), so that value is row[0].
let related_alerts = [];
const row = response.data?.[0]?.data?.[0]?.row ?? response.data?.[0]?.row;
if (Array.isArray(row) && Array.isArray(row[0])) {
  related_alerts = row[0];
} else if (Array.isArray(row) && Array.isArray(row[0]?.related_alerts)) {
  related_alerts = row[0].related_alerts;
} else if (Array.isArray(response.data?.[0]?.row?.[0])) {
  related_alerts = response.data[0].row[0];
}
related_alerts = Array.isArray(related_alerts) ? related_alerts.filter(Boolean) : [];

return [{ json: {
  ...alert,
  related_alerts,
  correlation_summary: {
    related_alert_count: related_alerts.length,
    correlation_types: [...new Set(related_alerts.map(x => x.correlation_type).filter(Boolean))]
  }
}}];

const input = $json.body ?? $json;
const rule = input.rule ?? {};
const agent = input.agent ?? {};
const log = String(input.full_log ?? input.data?.full_log ?? input.message ?? '');
const description = String(rule.description ?? input.rule_description ?? 'Security alert');
const alertId = String(input.id ?? input.alert_id ?? `sim-${Date.now()}`);

const ips = [...new Set(log.match(/\b(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}\b/g) || [])];
const hashes = [...new Set(log.match(/\b(?:[a-fA-F0-9]{32}|[a-fA-F0-9]{40}|[a-fA-F0-9]{64})\b/g) || [])];
const domains = [...new Set(log.match(/\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}\b/g) || [])];

return [{
  json: {
    alert_id: alertId,
    timestamp: input.timestamp ?? new Date().toISOString(),
    rule_id: String(rule.id ?? input.rule_id ?? 'unknown'),
    rule_description: description,
    rule_level: Number(rule.level ?? input.rule_level ?? 0),
    agent_id: String(agent.id ?? input.agent_id ?? 'unknown'),
    agent_name: String(agent.name ?? input.agent_name ?? 'unknown'),
    agent_ip: String(agent.ip ?? input.agent_ip ?? 'unknown'),
    full_log: log,
    entities: { ips, domains, hashes },
    source: 'simulated-wazuh'
  }
}];

