={{ {
  statement: "MERGE (a:Alert {id: $alert_id}) SET a.timestamp = datetime($timestamp), a.rule_id = $rule_id, a.description = $description, a.rule_level = $rule_level, a.full_log = $full_log, a.source = $source, a.updated_at = datetime() MERGE (h:Host {id: $agent_id}) SET h.name = $agent_name, h.ip = $agent_ip MERGE (a)-[:OBSERVED_ON]->(h) WITH a UNWIND $ips AS ip MERGE (i:IP {value: ip}) MERGE (a)-[:SOURCE_IP]->(i) RETURN a.id AS alert_id",
  parameters: {
    alert_id: $json.alert_id,
    timestamp: $json.timestamp,
    rule_id: $json.rule_id,
    description: $json.rule_description,
    rule_level: $json.rule_level,
    full_log: $json.full_log,
    source: $json.source,
    agent_id: $json.agent_id,
    agent_name: $json.agent_name,
    agent_ip: $json.agent_ip,
    ips: $json.entities.ips
  }
} }}

