const alert = $('Normalize Alert and Extract IOCs1').first().json;
const isPublicIPv4 = (ip) => {
  const p = ip.split('.').map(Number);
  if (p.length !== 4 || p.some(n => !Number.isInteger(n) || n < 0 || n > 255)) return false;
  return !(p[0] === 10 || p[0] === 127 || p[0] === 0 ||
    (p[0] === 192 && p[1] === 168) ||
    (p[0] === 172 && p[1] >= 16 && p[1] <= 31) ||
    (p[0] === 169 && p[1] === 254) ||
    p[0] >= 224);
};
const public_ips = alert.entities.ips.filter(isPublicIPv4);
return [{ json: { ...alert, public_ips, enrichment: [] } }];

const alert = $('Filter Public IPs1').first().json;
const vt = $('VirusTotal - IP Lookup1').isExecuted ? $('VirusTotal - IP Lookup1').first().json : {};
const abuse = $('AbuseIPDB - IP Check1').isExecuted ? $('AbuseIPDB - IP Check1').first().json : {};
const vtStats = vt.data?.attributes?.last_analysis_stats ?? {};
const abuseData = abuse.data ?? {};
const vtMalicious = Number(vtStats.malicious ?? 0);
const abuseScore = Number(abuseData.abuseConfidenceScore ?? 0);
return [{ json: {
  ...alert,
  enrichment: alert.public_ips.length ? [{
    ioc_type: 'ip',
    ioc_value: alert.public_ips[0],
    virustotal: { malicious: vtMalicious, stats: vtStats, lookup_status: vt.data ? 'success' : 'unavailable' },
    abuseipdb: { confidence_score: abuseScore, total_reports: Number(abuseData.totalReports ?? 0), lookup_status: abuse.data ? 'success' : 'unavailable' }
  }] : []
}}];

