const source = $('Parse Correlated Alerts').first().json;
let report = {};
try {
  const content = $json.choices?.[0]?.message?.content ?? '{}';
  report = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  report = { verdict: 'inconclusive', confidence: 0, executive_summary: 'AI response could not be parsed.', key_findings: [], mitre_context: [], recommended_actions: ['Review the alert manually.'], limitations: ['Invalid or non-JSON LLM response.'] };
}
const level = Math.max(0, Math.min(15, Number(source.rule_level || 0)));
const vtMal = Number(source.enrichment?.[0]?.virustotal?.malicious || 0);
const abuse = Number(source.enrichment?.[0]?.abuseipdb?.confidence_score || 0);
const risk = Math.min(100, Math.round((level / 15) * 40 + Math.min(vtMal * 5, 25) + (abuse / 100) * 25 + (source.entities.ips.length ? 5 : 0)));

return [{ json: {
  alert_id: source.alert_id,
  timestamp: source.timestamp,
  verdict: report.verdict || 'inconclusive',
  risk_score: risk,
  confidence: Number(report.confidence || 0),
  executive_summary: report.executive_summary || 'No summary returned.',
  key_findings: report.key_findings || [],
  mitre_context: report.mitre_context || source.mitre_mapping || [],
  mitre_mapping: source.mitre_mapping || [],
  related_alerts: source.related_alerts || [],
  correlation_summary: source.correlation_summary || { related_alert_count: 0, correlation_types: [] },
  recommended_actions: report.recommended_actions || [],
  limitations: [...(report.limitations || []), 'Risk score is a deterministic MVP heuristic; validate before operational use.', 'MITRE mappings are keyword-based candidate mappings and require analyst validation.'],
  entities: source.entities,
  enrichment: source.enrichment,
  source_alert: { rule_id: source.rule_id, rule_description: source.rule_description, rule_level: source.rule_level, agent_id: source.agent_id, agent_name: source.agent_name }
}}];
